/* Visual study controls only. No API, storage, auth, payment or order effects. */
const announce=(text)=>{document.querySelector('#demo-status').textContent=text+' — visual prototype only.';};
document.querySelector('.menu-toggle')?.addEventListener('click',event=>{const trigger=event.currentTarget;const menu=document.querySelector('#mobile-menu');menu.hidden=!menu.hidden;trigger.setAttribute('aria-expanded',String(!menu.hidden));trigger.setAttribute('aria-label',menu.hidden?'Open menu':'Close menu');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=document.querySelector('#mobile-menu');if(menu&&!menu.hidden){menu.hidden=true;const trigger=document.querySelector('.menu-toggle');trigger.setAttribute('aria-expanded','false');trigger.focus();}}});
document.querySelectorAll('[data-finish]').forEach(button=>button.addEventListener('click',()=>{const smoked=button.dataset.finish==='smoked';document.querySelectorAll('[data-finish]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));document.querySelectorAll('[data-finish-label]').forEach(label=>label.textContent=smoked?'Smoked teak':'Natural teak');document.querySelectorAll('[data-package]').forEach(value=>value.textContent=smoked?'74 × 84 × 78 cm':'72 × 82 × 78 cm');document.querySelectorAll('[data-weight]').forEach(value=>value.textContent=smoked?'14.2 kg':'13.8 kg');document.querySelectorAll('[data-variant-context]').forEach(value=>value.textContent=smoked?'Smoked teak · ₹19,900':'Natural teak · ₹18,900');document.querySelectorAll('[data-product-price]').forEach(value=>value.textContent=smoked?'₹19,900':'₹18,900');document.querySelectorAll('.selected-product-image').forEach(image=>{image.src='../assets/'+(smoked?'chair-smoked':'chair')+'.png';image.alt='Aara lounge chair, '+(smoked?'smoked':'natural')+' teak finish';});announce('Finish changed. Shared assembled dimensions are preserved; variant package dimensions updated');}));
document.querySelectorAll('[data-gallery]').forEach(button=>button.addEventListener('click',()=>{const image=document.querySelector('.selected-product-image');const smoked=document.querySelector('[data-finish=smoked][aria-pressed=true]');image.src='../assets/'+(button.dataset.gallery==='room'?'room':smoked?'chair-smoked':'chair')+'.png';image.alt=button.dataset.gallery==='room'?'Room context, natural teak furniture':'Aara chair, '+(smoked?'smoked':'natural')+' teak object view';announce('Gallery image changed');}));
document.querySelectorAll('[data-quantity]').forEach(button=>button.addEventListener('click',()=>{const count=button.parentElement.querySelector('[data-count]');count.textContent=String(Math.max(1,Math.min(9,Number(count.textContent)+Number(button.dataset.quantity))));announce('Quantity preview changed. Totals in static fixtures are not recalculated');}));
document.querySelectorAll('[data-demo]').forEach(button=>button.addEventListener('click',event=>{event.preventDefault();announce(button.dataset.demo);}));
document.querySelectorAll('[data-demo-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();announce('Form preview; no information submitted');}));
